import { expect, test } from "bun:test";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { safeWindowsFileName } from "./platform.js";

test("renames a reserved device name", () => {
	expect(safeWindowsFileName("con")).toBe("_con");
});

test("linux-skipped observation", () => {
	const replacement = safeWindowsFileName("con");
	expect(replacement).toBe("_con");
	const dir = mkdtempSync(join(tmpdir(), "safe-win-"));
	try {
		writeFileSync(join(dir, replacement), "ok");
	} finally {
		rmSync(dir, { recursive: true, force: true });
	}
});
